7	
8	const initialState: DemoFormState = { status: "idle" };
9	
10	// ─── Field label style ────────────────────────────────────────────────────────
11	const labelStyle: React.CSSProperties = {
12	  fontFamily: FONT.sans,
13	  fontSize: 12,
14	  fontWeight: 600,
15	  color: BRAND.stoneDark,
16	  textTransform: "uppercase",
17	  letterSpacing: "0.04em",
18	  marginBottom: 6,
19	  display: "block",
