130	          backgroundPosition: "right 14px center",
131	          paddingRight: 36,
132	          cursor: "pointer",
133	        }}
134	        onFocus={() => setFocused(true)}
135	        onBlur={() => setFocused(false)}
136	      >
137	        {options.map((opt) => (
138	          <option key={opt.value} value={opt.value} disabled={opt.disabled}>
139	            {opt.label}
140	          </option>
