235	          }}
236	          aria-hidden="true"
237	        >
238	          <Check size={24} color={BRAND.sage} strokeWidth={2.5} />
239	        </div>
240	        <h3
241	          style={{
242	            fontFamily: FONT.serif,
243	            fontSize: 28,
244	            color: BRAND.onyx,
245	            fontWeight: 400,
246	            marginBottom: 12,
247	          }}
248	        >
249	          You&rsquo;re booked.
250	        </h3>
251	        <p
252	          style={{
253	            fontFamily: FONT.sans,
254	            fontSize: 15,
255	            color: BRAND.stoneDark,
256	            lineHeight: 1.6,
257	            maxWidth: 380,
258	            margin: "0 auto",
259	          }}
260	        >
