322	        >
323	          <FormSelect
324	            label="Chairs"
325	            name="chairs"
326	            options={CHAIR_OPTIONS}
327	            error={errors.chairs}
328	            required
329	          />
330	          <FormSelect
331	            label="Preferred time"
332	            name="preferredTime"
333	            options={TIME_OPTIONS}
334	            error={errors.preferredTime}
335	            required
336	          />
337	        </div>
338	
339	        <FormField
340	          label="What are you using now?"
341	          name="currentTool"
342	          type="text"
343	          placeholder="Fresha, spreadsheets, pen & paper…"
344	          error={errors.currentTool}
345	          required
346	        />
347	        <FormTextarea
348	          label="Anything else we should know?"
349	          name="notes"
350	          placeholder="Specific pain points, questions, or special circumstances…"
351	          error={errors.notes}
352	          rows={3}
353	        />
354	
355	        <button
356	          type="submit"
357	          disabled={isPending}
358	          style={{
359	            display: "flex",
360	            alignItems: "center",
361	            justifyContent: "center",
362	            gap: 8,
363	            width: "100%",
364	            padding: "14px 20px",
365	            borderRadius: 100,
366	            background: isPending ? BRAND.coal : BRAND.onyx,
367	            color: BRAND.bone,
368	            fontFamily: FONT.sans,
369	            fontSize: 15,
370	            fontWeight: 600,
371	            border: "none",
372	            cursor: isPending ? "wait" : "pointer",
373	            opacity: isPending ? 0.7 : 1,
374	            transition: "opacity 0.15s ease, background 0.15s ease",
375	            marginTop: 8,
