383	        <p
384	          style={{
385	            fontFamily: FONT.sans,
386	            fontSize: 12,
387	            color: BRAND.stoneFaint,
388	            textAlign: "center",
389	            marginTop: 12,
390	            marginBottom: 0,
391	          }}
392	        >
393	          We respond within one business day. No calendar tetris.
394	        </p>
395	      </form>
396	    </div>
397	  );
398	}
