// ─── ContactForm ──────────────────────────────────────────────────────────────
export function ContactForm() {
  const [state, formAction, isPending] = useActionState(submitContact, initialState);

  const cardStyle: React.CSSProperties = {
    background: BRAND.white,
    borderRadius: 18,
    padding: "32px 28px",
    boxShadow: SHADOW.card,
    border: `1px solid ${BRAND.borderSoft}`,
  };

  // ─── Success state ────────────────────────────────────────────────────────
  if (state.status === "success") {
    return (
      <div style={{ ...cardStyle, textAlign: "center" }}>
        <div
          style={{
            width: 56,
            height: 56,
            borderRadius: "50%",
            background: BRAND.sageWash,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            margin: "0 auto 20px",
          }}
          aria-hidden="true"
        >
          <Check size={24} color={BRAND.sage} strokeWidth={2.5} />
        </div>
        <h3
          style={{
            fontFamily: FONT.serif,
            fontSize: 28,
            color: BRAND.onyx,
            fontWeight: 400,
            marginBottom: 12,
          }}
        >
          Message sent.
        </h3>
        <p
          style={{
            fontFamily: FONT.sans,
            fontSize: 15,
            color: BRAND.stoneDark,
            lineHeight: 1.6,
            maxWidth: 380,
            margin: "0 auto",
          }}
        >
          {state.message}
        </p>
      </div>
    );
  }

  // ─── Form ─────────────────────────────────────────────────────────────────
  const errors = state.errors ?? {};

  return (
    <div style={cardStyle}>
      {state.status === "error" && state.message && (
        <div
          role="alert"
          style={{
            padding: "10px 14px",
            background: BRAND.crimsonSoft,
            color: BRAND.crimson,
            borderRadius: 8,
            fontFamily: FONT.sans,
            fontSize: 13,
            marginBottom: 16,
          }}
        >
          {state.message}
        </div>
      )}

      <form action={formAction} noValidate>
        <FormField
          label="Your name"
          name="name"
          type="text"
          placeholder="Jane Doe"
          error={errors.name}
          required
        />
        <FormField
          label="Email"
          name="email"
          type="email"
          placeholder="jane@yourstudio.com"
          error={errors.email}
          required
        />
        <FormSelect
          label="Topic"
          name="topic"
          options={TOPIC_OPTIONS}
          error={errors.topic}
          required
        />
        <FormTextarea
          label="Message"
          name="message"
          placeholder="Tell us what's on your mind…"
          error={errors.message}
          rows={5}
        />

        <button
          type="submit"
          disabled={isPending}
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: 8,
            width: "100%",
            padding: "14px 20px",
            borderRadius: 100,
            background: isPending ? BRAND.coal : BRAND.onyx,
            color: BRAND.bone,
            fontFamily: FONT.sans,
            fontSize: 15,
            fontWeight: 600,
            border: "none",
            cursor: isPending ? "wait" : "pointer",
            opacity: isPending ? 0.7 : 1,
            transition: "opacity 0.15s ease, background 0.15s ease",
            marginTop: 8,
          }}
          aria-busy={isPending}
        >
          {isPending ? "Sending…" : "Send message"}
          {!isPending && <ArrowRight size={15} strokeWidth={2} />}
        </button>

        <p
          style={{
            fontFamily: FONT.sans,
            fontSize: 12,
            color: BRAND.stoneFaint,
            textAlign: "center",
            marginTop: 12,
            marginBottom: 0,
          }}
        >
          We respond within one business day.
        </p>
      </form>
    </div>
  );
}

